# owner: platform
"""Seat students in rows, ordered by last name."""

from typing import List

from rosterkit.models import Student

# ---
def arrange_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    check_seating(students, seats_per_row)
    ordered = sorted(students, key=last_name_of)
    return format_rows(split_rows(ordered, seats_per_row))

# ---
def last_name_of(student: Student) -> str:
    """Sort key: the student's last name."""
    return student.last_name

# ---
def check_seating(
    students: List[Student], seats_per_row: int
) -> None:
    """Refuse seat counts and empty rosters."""
    if seats_per_row <= 0:
        raise ValueError(f"bad seat count: {seats_per_row}")
    if not students:
        raise ValueError("no students to seat")

# ---
def split_rows(
    ordered: List[Student], seats_per_row: int
) -> List[List[Student]]:
    """Chunk an ordered list into rows of one width."""
    return [
        ordered[start:start + seats_per_row]
        for start in range(0, len(ordered), seats_per_row)
    ]

# ---
def format_rows(rows: List[List[Student]]) -> List[str]:
    """One text line per row, numbered from one."""
    lines = []
    for number, seated in enumerate(rows, 1):
        names = [item.display_name for item in seated]
        lines.append(f"Row {number}: " + " | ".join(names))
    return lines
